pub(crate) fn receive_original_five_lane_handoff_until(
    socket: UnixDatagram,
    timeout: Duration,
    gate: &Arc<SameActorPhaseGate>,
) -> Result<(File, OwnedFd), AgentdError> {
    let mut closing = CloseSameActorPhaseOnDrop::new(gate);
    gate.require_open()?;
    let _stop = gate.retain_original_datagram(&socket)?;
    let peer = root_pair(&socket, bounded_timeout(timeout, gate.deadline().instant())?)?;
    let (bootstrap, root) = receive_packet(
        &socket, bounded_timeout(timeout, gate.deadline().instant())?,
    )?;
    validate_bootstrap(&bootstrap)?;
    require_root_pin(&root, peer.pid as u32)?;
    gate.require_open()?;
    closing.disarm();
    Ok((bootstrap, root))
}

